import Phaser from 'phaser';
import { MainScene } from '../MainScene';
import { Noise } from '../utils/Noise';
import { TERRAIN_CONFIG, MAP_PRESETS } from '../../constants';
import { TerrainModifiers, SlopeInfo, MapPreset } from '../../types';
import { toIso, toIsoElev } from '../utils/iso';

export class TerrainSystem {
  private scene: MainScene;
  private heightGrid: Float32Array;
  private gridWidth: number;
  private gridHeight: number;
  private noise: Noise;
  public visualSprite: Phaser.GameObjects.Sprite | null = null;
  private riverCells: Set<number> = new Set(); // Grid indices of river cells
  private preset: MapPreset;
  private presetConfig: typeof MAP_PRESETS[MapPreset.STANDARD];

  constructor(scene: MainScene, mapWidth: number, mapHeight: number, seed?: number, preset: MapPreset = MapPreset.STANDARD) {
    this.scene = scene;
    this.gridWidth = Math.ceil(mapWidth / TERRAIN_CONFIG.CELL_SIZE);
    this.gridHeight = Math.ceil(mapHeight / TERRAIN_CONFIG.CELL_SIZE);
    this.heightGrid = new Float32Array(this.gridWidth * this.gridHeight);
    this.noise = new Noise(seed ? seed * 233280 : Math.random() * 233280);
    this.preset = preset;
    this.presetConfig = MAP_PRESETS[preset];
  }

  generateHeightMap(): void {
    const w = this.gridWidth;
    const h = this.gridHeight;
    const baseScale = TERRAIN_CONFIG.BASE_SCALE;
    const detailScale = TERRAIN_CONFIG.DETAIL_SCALE;
    const macroScale = TERRAIN_CONFIG.MACRO_SCALE;
    const macroAmp = TERRAIN_CONFIG.MACRO_AMPLITUDE;

    // Preset overrides
    const waterLevel = this.presetConfig.waterLevel;
    const heightMult = this.presetConfig.heightMultiplier;
    // Highlands: more aggressive power stretch for dramatic peaks
    const heightExp = this.preset === MapPreset.HIGHLANDS
      ? TERRAIN_CONFIG.HEIGHT_EXPONENT * 0.7
      : TERRAIN_CONFIG.HEIGHT_EXPONENT;

    const mapCenterX = w * TERRAIN_CONFIG.CELL_SIZE / 2;
    const mapCenterY = h * TERRAIN_CONFIG.CELL_SIZE / 2;
    const maxDist = Math.min(mapCenterX, mapCenterY);

    for (let gy = 0; gy < h; gy++) {
      for (let gx = 0; gx < w; gx++) {
        // World position at center of this grid cell
        const wx = gx * TERRAIN_CONFIG.CELL_SIZE + TERRAIN_CONFIG.CELL_SIZE / 2;
        const wy = gy * TERRAIN_CONFIG.CELL_SIZE + TERRAIN_CONFIG.CELL_SIZE / 2;

        // Three-octave noise: macro (continental basins) + base (hills/valleys) + detail (roughness)
        const macro = this.noise.perlin2(wx * macroScale, wy * macroScale) * macroAmp;
        const base = this.noise.perlin2(wx * baseScale, wy * baseScale);
        const detail = this.noise.perlin2(wx * detailScale, wy * detailScale) * TERRAIN_CONFIG.DETAIL_AMPLITUDE;

        let height = (macro + base + detail) * 0.5 + 0.5;
        height = Phaser.Math.Clamp(height, 0, 1);

        // Apply preset height multiplier (affects terrain roughness)
        if (heightMult !== 1.0) {
          const mid = 0.5;
          height = mid + (height - mid) * heightMult;
          height = Phaser.Math.Clamp(height, 0, 1);
        }

        // ISLAND preset: push edges below water, keep center as land
        if (this.preset === MapPreset.ISLAND) {
          const dx = wx - mapCenterX;
          const dy = wy - mapCenterY;
          const dist = Math.sqrt(dx * dx + dy * dy) / maxDist; // 0 at center, ~1 at edge
          // Smooth falloff: start reducing at 40% from center, fully water at 95%
          const falloff = dist < 0.4 ? 0 : (dist - 0.4) / 0.55;
          height -= falloff * 0.35;
          height = Phaser.Math.Clamp(height, 0, 1);
        }

        // Power stretch: push above-water heights toward peaks so more cells hit
        // scrub/stone biomes instead of everything clustering in grass/forest.
        if (height > waterLevel && heightExp < 1.0) {
          const t = (height - waterLevel) / (1 - waterLevel);
          const stretched = t ** heightExp;
          height = waterLevel + stretched * (1 - waterLevel);
        }

        this.heightGrid[gy * w + gx] = height;
      }
    }
  }

  getHeightAt(wx: number, wy: number): number {
    const gx = Math.floor(wx / TERRAIN_CONFIG.CELL_SIZE);
    const gy = Math.floor(wy / TERRAIN_CONFIG.CELL_SIZE);

    if (gx < 0 || gx >= this.gridWidth || gy < 0 || gy >= this.gridHeight) {
      return 0.5; // Default height outside map
    }

    return this.heightGrid[gy * this.gridWidth + gx];
  }

  getHeightInterpolated(wx: number, wy: number): number {
    const gx = wx / TERRAIN_CONFIG.CELL_SIZE;
    const gy = wy / TERRAIN_CONFIG.CELL_SIZE;
    const gxi = Math.floor(gx);
    const gyi = Math.floor(gy);
    const fx = gx - gxi;
    const fy = gy - gyi;

    if (gxi < 0 || gxi >= this.gridWidth - 1 || gyi < 0 || gyi >= this.gridHeight - 1) {
      return this.getHeightAt(wx, wy);
    }

    const idx = gyi * this.gridWidth + gxi;
    const h00 = this.heightGrid[idx];
    const h10 = this.heightGrid[idx + 1];
    const h01 = this.heightGrid[idx + this.gridWidth];
    const h11 = this.heightGrid[idx + this.gridWidth + 1];

    // Bilinear interpolation
    const top = h00 * (1 - fx) + h10 * fx;
    const bottom = h01 * (1 - fx) + h11 * fx;
    return top * (1 - fy) + bottom * fy;
  }

  getSlopeAt(wx: number, wy: number): SlopeInfo {
    const cx = wx / TERRAIN_CONFIG.CELL_SIZE;
    const cy = wy / TERRAIN_CONFIG.CELL_SIZE;
    const gxi = Math.floor(cx);
    const gyi = Math.floor(cy);

    if (gxi < 1 || gxi >= this.gridWidth - 1 || gyi < 1 || gyi >= this.gridHeight - 1) {
      return { slope: 0, isBuildable: true };
    }

    const idx = gyi * this.gridWidth + gxi;
    const hCenter = this.heightGrid[idx];
    const hRight = this.heightGrid[idx + 1];
    const hBottom = this.heightGrid[idx + this.gridWidth];

    // Slope magnitude from horizontal & vertical deltas
    const dx = Math.abs(hRight - hCenter);
    const dy = Math.abs(hBottom - hCenter);
    const slope = Math.sqrt(dx * dx + dy * dy);

    return {
      slope,
      isBuildable: slope <= TERRAIN_CONFIG.MAX_BUILDABLE_SLOPE
    };
  }

  getMovementModifier(wx: number, wy: number): number {
    const slopeInfo = this.getSlopeAt(wx, wy);
    if (slopeInfo.slope < TERRAIN_CONFIG.SLOPE_THRESHOLD) {
      return 1.0; // Flat terrain — no modifier
    }

    // Directional check: sample height ahead vs behind
    // Use interpolated height for smooth transitions
    const h = this.getHeightInterpolated(wx, wy);
    const hForward = this.getHeightInterpolated(wx + TERRAIN_CONFIG.CELL_SIZE * 0.5, wy + TERRAIN_CONFIG.CELL_SIZE * 0.5);

    const diffForward = hForward - h;

    if (diffForward > TERRAIN_CONFIG.SLOPE_THRESHOLD) {
      // Uphill — slower
      return TERRAIN_CONFIG.UPHILL_SPEED_PENALTY;
    } else if (diffForward < -TERRAIN_CONFIG.SLOPE_THRESHOLD) {
      // Downhill — faster
      return TERRAIN_CONFIG.DOWNHILL_SPEED_BONUS;
    }

    return 1.0;
  }

  getCombatModifiers(attackerX: number, attackerY: number, defenderX: number, defenderY: number): TerrainModifiers {
    const defHeight = this.getHeightInterpolated(defenderX, defenderY);
    const atkHeight = this.getHeightInterpolated(attackerX, attackerY);
    const diff = atkHeight - defHeight;

    let attackBonus = 0;
    let defenseBonus = 0;

    if (Math.abs(diff) > TERRAIN_CONFIG.HEIGHT_DIFF_THRESHOLD) {
      if (diff > 0) {
        // Attacker on high ground
        attackBonus = TERRAIN_CONFIG.HIGH_GROUND_ATTACK_BONUS;
        defenseBonus = 0; // Defender already at low ground
      } else {
        // Defender on high ground
        attackBonus = 0;
        defenseBonus = TERRAIN_CONFIG.HIGH_GROUND_DEFENSE_BONUS;
      }
    }

    return {
      movementSpeed: this.getMovementModifier(attackerX, attackerY),
      attackBonus,
      defenseBonus
    };
  }

  private hash11(seed: number): number {
    // simple deterministic hash from integer seed → [0,1)
    seed = (seed * 16807) % 2147483647;
    return (seed & 0x7fffffff) / 2147483647;
  }

  applyVisualTinting(): void {
    if (this.visualSprite) { this.visualSprite.destroy(); this.visualSprite = null; }
    if (this.scene.textures.exists('_terrainTint')) this.scene.textures.remove('_terrainTint');

    const {
      CELL_SIZE: CS, BIOMES, BIOME_DITHER, TEX_PERIOD,
      LIGHT_DIR_X, LIGHT_DIR_Y, LIGHT_DIR_Z,
      LIGHT_AMBIENT, LIGHT_DIFFUSE, NORMAL_STRENGTH, HEIGHT_SHADE,
      WATER_LEVEL: _waterLevel, // Use preset water level instead
      CLIFF_SLOPE_START, CLIFF_SLOPE_FULL, CLIFF_FACE_MIN_DROP,
    } = TERRAIN_CONFIG;
    const WATER_LEVEL = this.presetConfig.waterLevel;
    const w = this.gridWidth;
    const h = this.gridHeight;
    const src = this.scene.textures;
    const period = Math.max(64, TEX_PERIOD ?? 768);
    const textureKeys = ['terrain_sand', 'terrain_swamp', 'terrain_grass', 'terrain_jungle', 'terrain_forest', 'terrain_tundra', 'terrain_scrub', 'terrain_stone'];
    const STONE_IDX = BIOMES.length - 1;

    const patterns: (CanvasPattern | string | null)[] = BIOMES.map((b, i) => {
      if (i === 0) return null;
      const fallback = `rgb(${b.color.r},${b.color.g},${b.color.b})`;
      const key = textureKeys[i - 1];
      if (!src.exists(key)) return fallback;
      const tex = src.get(key);
      const img = (typeof (tex as { getSourceImage?: () => CanvasImageSource }).getSourceImage === 'function'
        ? (tex as { getSourceImage: () => CanvasImageSource }).getSourceImage()
        : (tex as { image?: CanvasImageSource }).image) as HTMLImageElement | HTMLCanvasElement | undefined;
      if (!img) return fallback;
      const sw = ('naturalWidth' in img ? (img as HTMLImageElement).naturalWidth : 0) || img.width || period;
      const sh = ('naturalHeight' in img ? (img as HTMLImageElement).naturalHeight : 0) || img.height || period;
      const c = document.createElement('canvas');
      c.width = period;
      c.height = period;
      const cctx = c.getContext('2d')!;
      cctx.imageSmoothingEnabled = true;
      cctx.imageSmoothingQuality = 'high';
      cctx.drawImage(img, 0, 0, sw, sh, 0, 0, period, period);
      return cctx.createPattern(c, 'repeat') ?? fallback;
    });

    const solid = (i: number) => {
      const bi = Math.max(1, Math.min(BIOMES.length - 1, i));
      const c = BIOMES[bi].color;
      return `rgb(${c.r},${c.g},${c.b})`;
    };

    const stonePat = patterns[STONE_IDX] ?? solid(STONE_IDX);

    const getBiomeBlend = (height: number): { a: number; b: number; t: number } => {
      let idx = 0;
      for (let i = BIOMES.length - 1; i >= 0; i--) {
        if (height >= BIOMES[i].minHeight) { idx = i; break; }
      }
      if (idx <= 0) return { a: 0, b: 0, t: 0 };
      if (idx >= BIOMES.length - 1) {
        const cur = BIOMES[idx].minHeight;
        const prev = BIOMES[idx - 1].minHeight;
        const gap = Math.max(1e-6, cur - (Number.isFinite(prev) ? prev : WATER_LEVEL));
        const half = Math.min(BIOME_DITHER, gap * 0.45);
        const tLo = cur - half;
        const tHi = cur + half;
        if (height >= tLo && height < tHi) {
          const raw = (height - tLo) / (tHi - tLo);
          const t = raw * raw * (3 - 2 * raw);
          return { a: idx - 1, b: idx, t };
        }
        return { a: idx, b: idx, t: 0 };
      }

      const next = BIOMES[idx + 1].minHeight;
      const gapUp = Math.max(1e-6, next - BIOMES[idx].minHeight);
      const halfUp = Math.min(BIOME_DITHER, gapUp * 0.45);
      const upLo = next - halfUp;
      const upHi = next + halfUp;
      if (height >= upLo && height < upHi) {
        const raw = (height - upLo) / (upHi - upLo);
        const t = raw * raw * (3 - 2 * raw);
        return { a: idx, b: idx + 1, t };
      }

      const cur = BIOMES[idx].minHeight;
      const prevH = BIOMES[idx - 1].minHeight;
      const gapDn = Math.max(1e-6, cur - (Number.isFinite(prevH) ? prevH : WATER_LEVEL));
      const halfDn = Math.min(BIOME_DITHER, gapDn * 0.45);
      const dnLo = cur - halfDn;
      const dnHi = cur + halfDn;
      if (height >= dnLo && height < dnHi) {
        const raw = (height - dnLo) / (dnHi - dnLo);
        const t = raw * raw * (3 - 2 * raw);
        return { a: idx - 1, b: idx, t };
      }

      return { a: idx, b: idx, t: 0 };
    };

    const rockFromSlope = (slope: number): number => {
      const lo = CLIFF_SLOPE_START ?? 0.18;
      const hi = CLIFF_SLOPE_FULL ?? 0.38;
      if (slope <= lo) return 0;
      if (slope >= hi) return 1;
      const raw = (slope - lo) / Math.max(1e-6, hi - lo);
      return raw * raw * (3 - 2 * raw);
    };

    // Shared corner height field (w+1)×(h+1) — every diamond edge uses identical verts → no height seams.
    const cw = w + 1;
    const ch = h + 1;
    const cornerH = new Float32Array(cw * ch);
    for (let cy = 0; cy < ch; cy++) {
      for (let cx = 0; cx < cw; cx++) {
        cornerH[cy * cw + cx] = this.getHeightInterpolated(cx * CS, cy * CS);
      }
    }

    let maxGridHeight = 0;
    for (let i = 0; i < w * h; i++) {
      const hgt = this.heightGrid[i];
      if (hgt > maxGridHeight) maxGridHeight = hgt;
    }
    // Corners can be slightly above grid max after interp edges — pad AABB.
    for (let i = 0; i < cornerH.length; i++) {
      if (cornerH[i] > maxGridHeight) maxGridHeight = cornerH[i];
    }
    const maxLift = Math.max(0, maxGridHeight - WATER_LEVEL) * TERRAIN_CONFIG.HEIGHT_LIFT;

    const cornerPts = [toIso(0, 0), toIso(w * CS, 0), toIso(w * CS, h * CS), toIso(0, h * CS)];
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const p of cornerPts) {
      if (p.x < minX) minX = p.x; if (p.x > maxX) maxX = p.x;
      if (p.y < minY) minY = p.y; if (p.y > maxY) maxY = p.y;
    }
    minY -= maxLift;
    const ox = minX, oy = minY;
    const tw = Math.ceil(maxX - minX) + 2;
    const th = Math.ceil(maxY - minY) + 2;

    const cvs = document.createElement('canvas');
    cvs.width = tw;
    cvs.height = th;
    const ctx = cvs.getContext('2d')!;
    // Slight overscan so AA fringes aren't clipped.
    ctx.translate(1, 1);

    const llen = Math.hypot(LIGHT_DIR_X, LIGHT_DIR_Y, LIGHT_DIR_Z) || 1;
    const lx = LIGHT_DIR_X / llen;
    const ly = LIGHT_DIR_Y / llen;
    const lz = LIGHT_DIR_Z / llen;

    const faceMin = CLIFF_FACE_MIN_DROP ?? 0.10;

    // Precompute smoothed lighting per cell (3×3) so adjacent diamonds don't form a dark grid.
    const litGrid = new Float32Array(w * h);
    const rockGrid = new Float32Array(w * h);
    for (let gy = 0; gy < h; gy++) {
      for (let gx = 0; gx < w; gx++) {
        const height = this.heightGrid[gy * w + gx];
        const hL = gx > 0 ? this.heightGrid[gy * w + (gx - 1)] : height;
        const hR = gx < w - 1 ? this.heightGrid[gy * w + (gx + 1)] : height;
        const hU = gy > 0 ? this.heightGrid[(gy - 1) * w + gx] : height;
        const hD = gy < h - 1 ? this.heightGrid[(gy + 1) * w + gx] : height;
        const dx = Math.max(Math.abs(hR - height), Math.abs(height - hL));
        const dy = Math.max(Math.abs(hD - height), Math.abs(height - hU));
        const slope = Math.hypot(dx, dy);
        rockGrid[gy * w + gx] = rockFromSlope(slope);

        const nx = -(hR - hL) * 0.5 * NORMAL_STRENGTH;
        const ny = -(hD - hU) * 0.5 * NORMAL_STRENGTH;
        const nz = 1;
        const nlen = Math.hypot(nx, ny, nz) || 1;
        const ndotl = Math.max(0, (nx * lx + ny * ly + nz * lz) / nlen);
        let lit = LIGHT_AMBIENT + LIGHT_DIFFUSE * ndotl;
        const hTerm = (height - WATER_LEVEL) / Math.max(1e-6, 1 - WATER_LEVEL);
        lit *= 1 + (hTerm - 0.35) * (HEIGHT_SHADE ?? 0.28);
        lit *= 1 - rockGrid[gy * w + gx] * 0.18;
        litGrid[gy * w + gx] = Math.max(0.2, Math.min(1.12, lit));
      }
    }
    // Box-blur lighting once to kill hard cell boundaries.
    const litSmooth = new Float32Array(w * h);
    for (let gy = 0; gy < h; gy++) {
      for (let gx = 0; gx < w; gx++) {
        let sum = 0, n = 0;
        for (let oy = -1; oy <= 1; oy++) {
          for (let ox = -1; ox <= 1; ox++) {
            const x = gx + ox, y = gy + oy;
            if (x < 0 || y < 0 || x >= w || y >= h) continue;
            sum += litGrid[y * w + x];
            n++;
          }
        }
        litSmooth[gy * w + gx] = sum / n;
      }
    }

    // Land cells: draw if center OR any corner is above water (seals shoreline holes).
    const isLandish = (gx: number, gy: number): boolean => {
      const height = this.heightGrid[gy * w + gx];
      if (height >= WATER_LEVEL - 0.01) return true;
      const i = gy * cw + gx;
      return (
        cornerH[i] >= WATER_LEVEL ||
        cornerH[i + 1] >= WATER_LEVEL ||
        cornerH[i + cw] >= WATER_LEVEL ||
        cornerH[i + cw + 1] >= WATER_LEVEL
      );
    };

    for (let gy = 0; gy < h; gy++) {
      for (let gx = 0; gx < w; gx++) {
        if (!isLandish(gx, gy)) continue;

        const height = this.heightGrid[gy * w + gx];
        const wx = gx * CS;
        const wy = gy * CS;

        // Shared corner heights — identical verts on shared edges.
        const h0 = cornerH[gy * cw + gx];
        const h1 = cornerH[gy * cw + gx + 1];
        const h2 = cornerH[(gy + 1) * cw + gx + 1];
        const h3 = cornerH[(gy + 1) * cw + gx];

        // Lift underwater corners to water plane so shore quads seal against the lake.
        const e0 = h0 < WATER_LEVEL ? WATER_LEVEL : h0;
        const e1 = h1 < WATER_LEVEL ? WATER_LEVEL : h1;
        const e2 = h2 < WATER_LEVEL ? WATER_LEVEL : h2;
        const e3 = h3 < WATER_LEVEL ? WATER_LEVEL : h3;

        const rockT = rockGrid[gy * w + gx];
        const sampleH = Math.max(height, WATER_LEVEL);
        const { a, b, t } = getBiomeBlend(sampleH);
        const baseIdx = Math.max(1, a);
        const topIdx = Math.max(1, b);
        const patA = patterns[baseIdx] ?? solid(baseIdx);
        const patB = patterns[topIdx] ?? solid(topIdx);

        const c0 = toIsoElev(wx, wy, e0);
        const c1 = toIsoElev(wx + CS, wy, e1);
        const c2 = toIsoElev(wx + CS, wy + CS, e2);
        const c3 = toIsoElev(wx, wy + CS, e3);

        const path = () => {
          ctx.beginPath();
          ctx.moveTo(c0.x - ox, c0.y - oy);
          ctx.lineTo(c1.x - ox, c1.y - oy);
          ctx.lineTo(c2.x - ox, c2.y - oy);
          ctx.lineTo(c3.x - ox, c3.y - oy);
          ctx.closePath();
        };

        // Fill + hairline stroke seals canvas AA cracks between shared edges.
        const fillSeal = (style: string | CanvasPattern, alpha = 1, sealColor?: string) => {
          path();
          ctx.globalAlpha = alpha;
          ctx.fillStyle = style;
          ctx.fill();
          if (sealColor) {
            ctx.strokeStyle = sealColor;
            ctx.lineWidth = 0.6;
            ctx.lineJoin = 'round';
            ctx.globalAlpha = Math.min(0.25, alpha * 0.25);
            ctx.stroke();
          }
        };

        fillSeal(patA as string | CanvasPattern, 1, solid(baseIdx));

        if (t > 0.001 && topIdx !== baseIdx) {
          fillSeal(patB as string | CanvasPattern, t);
        }

        if (rockT > 0.02) {
          fillSeal(stonePat as string | CanvasPattern, rockT);
        }
        const lit = litSmooth[gy * w + gx];
        const s = Math.round(Math.min(255, lit * 255));
        path();
        ctx.globalCompositeOperation = 'multiply';
        ctx.fillStyle = `rgb(${s},${s},${s})`;
        ctx.fill();
        // Subtle stroke for multiply pass
        ctx.strokeStyle = `rgb(${s},${s},${s})`;
        ctx.lineWidth = 0.6;
        ctx.globalAlpha = 0.15;
        ctx.stroke();

        const hL = gx > 0 ? this.heightGrid[gy * w + (gx - 1)] : height;
        const hR = gx < w - 1 ? this.heightGrid[gy * w + (gx + 1)] : height;
        const hU = gy > 0 ? this.heightGrid[(gy - 1) * w + gx] : height;
        const hD = gy < h - 1 ? this.heightGrid[(gy + 1) * w + gx] : height;
        const nx = -(hR - hL) * 0.5 * NORMAL_STRENGTH;
        const ny = -(hD - hU) * 0.5 * NORMAL_STRENGTH;
        const nlen = Math.hypot(nx, ny, 1) || 1;
        const ndotl = Math.max(0, (nx * lx + ny * ly + 1 * lz) / nlen);

        if (ndotl > 0.55 && lit > 0.85 && rockT < 0.35) {
          const ha = Math.min(0.22, (ndotl - 0.55) * 0.3);
          path();
          ctx.globalCompositeOperation = 'soft-light';
          ctx.fillStyle = `rgba(255,236,180,${ha.toFixed(3)})`;
          ctx.fill();
        }

        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = 1;

        // River blue tint — draw on river cells for visual identification
        if (this.riverCells.has(gy * w + gx)) {
          path();
          ctx.globalCompositeOperation = 'multiply';
          ctx.fillStyle = 'rgba(120,160,255,0.7)'; // Blue river tint
          ctx.fill();
        }

        // True cliff faces only — large neighbor drop. Small slopes used to paint crack lines.
        const eastH = gx < w - 1 ? this.heightGrid[gy * w + (gx + 1)] : height;
        const southH = gy < h - 1 ? this.heightGrid[(gy + 1) * w + gx] : height;

        if (eastH < height - faceMin) {
          const diff = height - eastH;
          const cliffAlpha = Math.min(0.65, 0.25 + diff * 1.2);
          // Bottom edge uses east cell's shared corners on the east edge.
          const botN = toIsoElev(wx + CS, wy, Math.max(eastH, WATER_LEVEL));
          const botS = toIsoElev(wx + CS, wy + CS, Math.max(eastH, WATER_LEVEL));
          const face = () => {
            ctx.beginPath();
            ctx.moveTo(c1.x - ox, c1.y - oy);
            ctx.lineTo(c2.x - ox, c2.y - oy);
            ctx.lineTo(botS.x - ox, botS.y - oy);
            ctx.lineTo(botN.x - ox, botN.y - oy);
            ctx.closePath();
          };
          face();
          ctx.fillStyle = stonePat as string | CanvasPattern;
          ctx.fill();
          face();
          ctx.fillStyle = `rgba(24,20,16,${cliffAlpha.toFixed(3)})`;
          ctx.fill();
        }

        if (southH < height - faceMin) {
          const diff = height - southH;
          const cliffAlpha = Math.min(0.65, 0.25 + diff * 1.2);
          const botW = toIsoElev(wx, wy + CS, Math.max(southH, WATER_LEVEL));
          const botE = toIsoElev(wx + CS, wy + CS, Math.max(southH, WATER_LEVEL));
          const face = () => {
            ctx.beginPath();
            ctx.moveTo(c3.x - ox, c3.y - oy);
            ctx.lineTo(c2.x - ox, c2.y - oy);
            ctx.lineTo(botE.x - ox, botE.y - oy);
            ctx.lineTo(botW.x - ox, botW.y - oy);
            ctx.closePath();
          };
          face();
          ctx.fillStyle = stonePat as string | CanvasPattern;
          ctx.fill();
          face();
          ctx.fillStyle = `rgba(24,20,16,${cliffAlpha.toFixed(3)})`;
          ctx.fill();
        }
      }
    }

    this.scene.textures.addCanvas('_terrainTint', cvs);
    // Compensate the 1px translate used for AA overscan.
    this.visualSprite = this.scene.add.sprite(ox - 1, oy - 1, '_terrainTint').setOrigin(0);
    this.visualSprite.setDepth(-10000);
    if (this.scene.worldLayer) this.scene.worldLayer.add(this.visualSprite);
  }

  getHeightMapData(): Float32Array {
    return this.heightGrid;
  }

  getGridDimensions(): { width: number; height: number; cellSize: number } {
    return {
      width: this.gridWidth,
      height: this.gridHeight,
      cellSize: TERRAIN_CONFIG.CELL_SIZE
    };
  }

  /** Get the effective water level for this map (preset-aware). */
  getWaterLevel(): number {
    return this.presetConfig.waterLevel;
  }

  /** Get the current map preset. */
  getPreset(): MapPreset {
    return this.preset;
  }

  /**
   * Return the biome label ('sand','grass','forest','scrub','stone','deep')
   * at a world position using interpolated height and BIOMES thresholds.
   * No slope/dither — pure height → biome for gameplay (farm yield).
   */
  getBiomeLabel(wx: number, wy: number): string {
    const h = this.getHeightInterpolated(wx, wy);
    const biomes = TERRAIN_CONFIG.BIOMES;
    let idx = 0;
    for (let i = biomes.length - 1; i >= 0; i--) {
      if (h >= biomes[i].minHeight) { idx = i; break; }
    }
    return biomes[idx]?.label ?? 'deep';
  }
  /**
   * Quick check: is the terrain forest at (worldX, worldY)?
   * Used for forest concealment combat bonuses.
   */
  isForestAt(worldX: number, worldY: number): boolean {
    return this.getBiomeLabel(worldX, worldY) === 'forest';
  }

  /**
   * Generate river paths that follow low terrain valleys.
   * Rivers create natural chokepoints on the map.
   * Call after generateHeightMap() and before applyVisualTinting().
   */
  generateRivers(): void {
    const riverCount = this.presetConfig.riverCount;
    const { RIVER_WIDTH_CELLS, RIVER_MIN_HEIGHT, RIVER_MAX_HEIGHT } = TERRAIN_CONFIG;
    const w = this.gridWidth;
    const h = this.gridHeight;

    // Use deterministic hash from noise seed for river placement
    let seedCounter = 12345;
    const nextRand = () => {
      seedCounter = (seedCounter * 16807) % 2147483647;
      return (seedCounter & 0x7fffffff) / 2147483647;
    };

    for (let river = 0; river < riverCount; river++) {
      // Pick a random start point along the map edges at mid-elevation
      const edge = Math.floor(nextRand() * 4); // 0=top, 1=right, 2=bottom, 3=left
      let startX: number, startY: number;

      if (edge === 0) { // top
        startX = Math.floor(nextRand() * w);
        startY = 0;
      } else if (edge === 1) { // right
        startX = w - 1;
        startY = Math.floor(nextRand() * h);
      } else if (edge === 2) { // bottom
        startX = Math.floor(nextRand() * w);
        startY = h - 1;
      } else { // left
        startX = 0;
        startY = Math.floor(nextRand() * h);
      }

      // Trace river path downhill
      const path: { gx: number; gy: number }[] = [];
      let gx = startX;
      let gy = startY;
      const maxSteps = w + h; // Prevent infinite loops

      for (let step = 0; step < maxSteps; step++) {
        path.push({ gx, gy });

        // Find lowest neighbor
        let bestGx = gx, bestGy = gy;
        let bestHeight = this.heightGrid[gy * w + gx];

        for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            if (dx === 0 && dy === 0) continue;
            const nx = gx + dx;
            const ny = gy + dy;
            if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;

            const nh = this.heightGrid[ny * w + nx];
            if (nh < bestHeight) {
              bestHeight = nh;
              bestGx = nx;
              bestGy = ny;
            }
          }
        }

        // Stop if reached water or no lower neighbor
        if (bestHeight < TERRAIN_CONFIG.WATER_LEVEL || (bestGx === gx && bestGy === gy)) {
          break;
        }

        // Stop if height is too high (river shouldn't climb mountains)
        if (bestHeight > RIVER_MAX_HEIGHT) {
          break;
        }

        gx = bestGx;
        gy = bestGy;
      }

      // Mark cells along path as river (with width)
      for (const pt of path) {
        for (let dy = -RIVER_WIDTH_CELLS; dy <= RIVER_WIDTH_CELLS; dy++) {
          for (let dx = -RIVER_WIDTH_CELLS; dx <= RIVER_WIDTH_CELLS; dx++) {
            const rx = pt.gx + dx;
            const ry = pt.gy + dy;
            if (rx < 0 || rx >= w || ry < 0 || ry >= h) continue;

            // Only mark if in valid height range
            const cellHeight = this.heightGrid[ry * w + rx];
            if (cellHeight >= RIVER_MIN_HEIGHT && cellHeight <= RIVER_MAX_HEIGHT) {
              this.riverCells.add(ry * w + rx);
            }
          }
        }
      }
    }
  }

  /**
   * Quick check: is the terrain a river at (worldX, worldY)?
   * Used for river crossing penalties.
   */
  isRiverAt(worldX: number, worldY: number): boolean {
    const gx = Math.floor(worldX / TERRAIN_CONFIG.CELL_SIZE);
    const gy = Math.floor(worldY / TERRAIN_CONFIG.CELL_SIZE);
    if (gx < 0 || gx >= this.gridWidth || gy < 0 || gy >= this.gridHeight) {
      return false;
    }
    return this.riverCells.has(gy * this.gridWidth + gx);
  }

  /**
   * Get movement speed multiplier for river crossings.
   * Returns 0.5 (half speed) for river cells, 1.0 otherwise.
   */
  getRiverCrossingPenalty(worldX: number, worldY: number): number {
    return this.isRiverAt(worldX, worldY) ? TERRAIN_CONFIG.RIVER_CROSSING_SPEED_PENALTY : 1.0;
  }
  /**
   * Raise all height-grid cells within `radius` world-pixels of (wx, wy)
   * to at least `minHeight`. Call after generateHeightMap() to guarantee
   * dry land at spawn points / bases.
   */
  flattenAroundWorld(wx: number, wy: number, radius: number, minHeight: number): void {
    const cellSize = TERRAIN_CONFIG.CELL_SIZE;
    const gx0 = Math.max(0, Math.floor((wx - radius) / cellSize));
    const gy0 = Math.max(0, Math.floor((wy - radius) / cellSize));
    const gx1 = Math.min(this.gridWidth - 1, Math.ceil((wx + radius) / cellSize));
    const gy1 = Math.min(this.gridHeight - 1, Math.ceil((wy + radius) / cellSize));
    const r2 = radius * radius;
    for (let gy = gy0; gy <= gy1; gy++) {
      for (let gx = gx0; gx <= gx1; gx++) {
        const cx = gx * cellSize + cellSize / 2;
        const cy = gy * cellSize + cellSize / 2;
        const dx = cx - wx;
        const dy = cy - wy;
        if (dx * dx + dy * dy > r2) continue;
        const idx = gy * this.gridWidth + gx;
        if (this.heightGrid[idx] < minHeight) {
          this.heightGrid[idx] = minHeight;
        }
      }
    }
  }


  /**
   * Return the biome label at a world coordinate, matching the baked terrain tint.
   * Uses the same dither logic as applyVisualTinting so trees match what the player sees.
   */
  getBiomeAt(wx: number, wy: number): string {
    const h = this.getHeightAt(wx, wy);
    const CS = TERRAIN_CONFIG.CELL_SIZE;
    const gx = Math.floor(wx / CS);
    const gy = Math.floor(wy / CS);

    // Steep hillsides count as stone so trees/spawners skip cliffs.
    const slope = this.getSlopeAt(wx, wy).slope;
    const lo = TERRAIN_CONFIG.CLIFF_SLOPE_START ?? 0.12;
    const hi = TERRAIN_CONFIG.CLIFF_SLOPE_FULL ?? 0.28;
    if (slope >= (lo + hi) * 0.5) return 'stone';

    // Soft-blend match: pick dominant biome from height (same thresholds as bake).
    let idx = 0;
    for (let i = TERRAIN_CONFIG.BIOMES.length - 1; i >= 0; i--) {
      if (h >= TERRAIN_CONFIG.BIOMES[i].minHeight) { idx = i; break; }
    }
    // In transition band, bias toward higher biome when past midpoint (dither kept for variety).
    const dither = this.hash11(gx * 7919 + gy * 6271);
    if (idx < TERRAIN_CONFIG.BIOMES.length - 1) {
      const next = TERRAIN_CONFIG.BIOMES[idx + 1].minHeight;
      const half = Math.min(TERRAIN_CONFIG.BIOME_DITHER, Math.max(1e-6, next - TERRAIN_CONFIG.BIOMES[idx].minHeight) * 0.45);
      if (h >= next - half && h < next + half) {
        const raw = (h - (next - half)) / (2 * half);
        if (dither < raw) idx = idx + 1;
      }
    }
    return TERRAIN_CONFIG.BIOMES[idx]?.label ?? 'grass';
  }
  destroy(): void {
    if (this.visualSprite) {
      this.visualSprite.destroy();
      this.visualSprite = null;
    }
    if (this.scene.textures.exists('_terrainTint')) {
      this.scene.textures.remove('_terrainTint');
    }
  }
}

import Phaser from 'phaser';
import { MainScene } from '../MainScene';
import { TILE_SIZE, GOLD_MINE_COUNT, MAP_PRESETS } from '../../constants';
import { MapMode, AnimalSpecies } from '../../types';
import { toIso } from '../utils/iso';
import { randomBetween } from '../utils/seededRandom';

export class MapGenerationSystem {
    private scene: MainScene;
    private rng: () => number;

    constructor(scene: MainScene, rng?: () => number) {
        this.scene = scene;
        this.rng = rng ?? Math.random;
    }

    createEnvironment() {
        const p1 = toIso(0, 0);
        const p2 = toIso(this.scene.mapWidth, 0);
        const p3 = toIso(this.scene.mapWidth, this.scene.mapHeight);
        const p4 = toIso(0, this.scene.mapHeight);

        const border = this.scene.add.graphics();
        border.lineStyle(8, 0x000000, 0.25);
        border.beginPath();
        border.moveTo(p1.x, p1.y);
        border.lineTo(p2.x, p2.y);
        border.lineTo(p3.x, p3.y);
        border.lineTo(p4.x, p4.y);
        border.closePath();
        border.strokePath();
        border.setDepth(-19000);

        const grid = this.scene.add.graphics();
        grid.lineStyle(1, 0x000000, 0.08);
        const gridSpacing = TILE_SIZE * 4;
        for (let x = 0; x <= this.scene.mapWidth; x += gridSpacing) {
            const gp1 = toIso(x, 0);
            const gp2 = toIso(x, this.scene.mapHeight);
            grid.moveTo(gp1.x, gp1.y);
            grid.lineTo(gp2.x, gp2.y);
        }
        for (let y = 0; y <= this.scene.mapHeight; y += gridSpacing) {
            const gp1 = toIso(0, y);
            const gp2 = toIso(this.scene.mapWidth, y);
            grid.moveTo(gp1.x, gp1.y);
            grid.lineTo(gp2.x, gp2.y);
        }
        grid.strokePath();
        grid.setDepth(-9999);
    }

    generateFertileZones() {
        const mult = MAP_PRESETS[this.scene.mapPreset]?.resourceMultiplier ?? 1.0;
        const zoneCount = Math.floor(((this.scene.mapWidth * this.scene.mapHeight) / (500 * 500)) * mult);
        for (let i = 0; i < zoneCount; i++) {
            const x = randomBetween(this.rng, 150, this.scene.mapWidth - 150);
            const y = randomBetween(this.rng, 150, this.scene.mapHeight - 150);
            const radius = randomBetween(this.rng, 100, 180);
            this.scene.fertileZones.push(new Phaser.Geom.Circle(x, y, radius));
            const iso = toIso(x, y);
            const graphics = this.scene.add.graphics();
            graphics.setDepth(-9500);
            graphics.fillStyle(0x5d4037, 0.12);
            graphics.fillEllipse(iso.x, iso.y, radius * 2, radius);
        }
    }

    generateForestsAndAnimals() {
        const mult = MAP_PRESETS[this.scene.mapPreset]?.resourceMultiplier ?? 1.0;
        const forestCount = Math.floor(((this.scene.mapWidth * this.scene.mapHeight) / (800 * 800)) * mult);
        for (let i = 0; i < forestCount; i++) {
            const fx = randomBetween(this.rng, 100, this.scene.mapWidth - 100);
            const fy = randomBetween(this.rng, 100, this.scene.mapHeight - 100);
            const fRadius = randomBetween(this.rng, 200, 450);
            const treeCount = Math.floor(fRadius * 0.4);
            for (let j = 0; j < treeCount; j++) {
                const angle = this.rng() * Math.PI * 2;
                const dist = Math.sqrt(this.rng()) * fRadius;
                const tx = fx + Math.cos(angle) * dist;
                const ty = fy + Math.sin(angle) * dist;
                if (Phaser.Math.Distance.Between(tx, ty, this.scene.mapWidth / 2, this.scene.mapHeight / 2) > 250) {
                    if (tx > 50 && tx < this.scene.mapWidth - 50 && ty > 50 && ty < this.scene.mapHeight - 50) {
                        this._trySpawnTreeAt(tx, ty);
                    }
                }
            }
            const animalCount = Math.floor(randomBetween(this.rng, 2, 5) * mult);
            for (let k = 0; k < animalCount; k++) {
                const angle = this.rng() * Math.PI * 2;
                const ax = fx + Math.cos(angle) * (fRadius * 0.8);
                const ay = fy + Math.sin(angle) * (fRadius * 0.8);
                if (Phaser.Math.Distance.Between(ax, ay, this.scene.mapWidth / 2, this.scene.mapHeight / 2) > 300) {
                    if (ax > 50 && ax < this.scene.mapWidth - 50 && ay > 50 && ay < this.scene.mapHeight - 50) {
                        // Pick species deterministically for seeded maps
                        const species = this.pickRandomSpecies();
                        this.scene.animalSystem.spawnAnimal(ax, ay, species);
                    }
                }
            }
        }
    }

    /** Pick a random animal species using the seeded RNG, matching SPECIES_WEIGHTS. */
    private pickRandomSpecies(): AnimalSpecies {
        const roll = this.rng() * 100;
        const SPECIES_WEIGHTS: { species: AnimalSpecies; weight: number }[] = [
            { species: AnimalSpecies.DEER, weight: 40 },
            { species: AnimalSpecies.RABBIT, weight: 30 },
            { species: AnimalSpecies.BOAR, weight: 20 },
            { species: AnimalSpecies.WOLF, weight: 10 },
        ];
        let cumulative = 0;
        for (const entry of SPECIES_WEIGHTS) {
            cumulative += entry.weight;
            if (roll < cumulative) return entry.species;
        }
        return AnimalSpecies.DEER;
    }

    /** Density multiplier per biome for tree spawning. */
    private static readonly TREE_DENSITY: Record<string, number> = {
        deep: 0,    // water — no trees
        sand: 0,    // shore — no trees
        swamp: 0.3, // wetlands — some water-loving trees
        grass: 0.15,// sparse
        jungle: 0.9,// dense tropical canopy
        forest: 1.0,// dense
        tundra: 0.05,// sparse cold-resistant
        scrub: 0.7, // thick
        stone: 0,   // bare rock — no trees
    };

    /** Check biome at (tx,ty) and spawn tree only if the RNG passes density threshold. */
    private _trySpawnTreeAt(tx: number, ty: number): void {
        const biome = this.scene.terrainSystem.getBiomeAt(tx, ty);
        const density = MapGenerationSystem.TREE_DENSITY[biome] ?? 0;
        if (density > 0 && this.rng() < density) {
            this.scene.entityFactory.spawnTree(tx, ty);
        }
    }

    /**
     * Spawn a guaranteed cluster of trees near a faction's starting Town Center.
     * Trees are placed in a ring between innerRadius (80px) and outerRadius (300px)
     * so they don't overlap building footprints but are within Lumber Camp harvesting range.
     */
    public spawnStartingForest(cx: number, cy: number, count: number = 20): void {
        const mult = MAP_PRESETS[this.scene.mapPreset]?.resourceMultiplier ?? 1.0;
        const adjustedCount = Math.max(5, Math.floor(count * mult));
        const innerRadius = 80;   // Avoid overlapping TC and initial buildings
        const outerRadius = 300;  // Within range of a Lumber Camp (effectRadius 200)
        const isInfinite = this.scene.mapMode === MapMode.INFINITE;
        const mapW = this.scene.mapWidth;
        const mapH = this.scene.mapHeight;

        for (let i = 0; i < adjustedCount; i++) {
            const angle = this.rng() * Math.PI * 2;
            // Use sqrt distribution to bias toward outer ring (more natural-looking)
            const dist = innerRadius + Math.sqrt(this.rng()) * (outerRadius - innerRadius);
            const tx = cx + Math.cos(angle) * dist;
            const ty = cy + Math.sin(angle) * dist;

            // Bounds check for fixed maps; infinite maps have no bounds
            if (isInfinite || (tx > 50 && tx < mapW - 50 && ty > 50 && ty < mapH - 50)) {
                this._trySpawnTreeAt(tx, ty);
            }
        }
    }

    /**
     * Spawn gold mine nodes near a faction's starting Town Center.
     * Placed in a ring between 100-280px so they don't overlap the TC
     * but are reachable without a dedicated building.
     */
    public spawnStartingGoldMines(cx: number, cy: number, count: number = GOLD_MINE_COUNT): void {
        const mult = MAP_PRESETS[this.scene.mapPreset]?.resourceMultiplier ?? 1.0;
        const adjustedCount = Math.max(2, Math.floor(count * mult));
        const innerRadius = 100;
        const outerRadius = 280;
        const isInfinite = this.scene.mapMode === MapMode.INFINITE;
        const mapW = this.scene.mapWidth;
        const mapH = this.scene.mapHeight;

        for (let i = 0; i < adjustedCount; i++) {
            const angle = (i / adjustedCount) * Math.PI * 2 + this.rng() * 0.5;
            const dist = innerRadius + this.rng() * (outerRadius - innerRadius);
            const tx = cx + Math.cos(angle) * dist;
            const ty = cy + Math.sin(angle) * dist;

            if (isInfinite || (tx > 50 && tx < mapW - 50 && ty > 50 && ty < mapH - 50)) {
                this.scene.entityFactory.spawnGoldMine(tx, ty);
            }
        }
    }
}

/**
 * Simple Perlin Noise generator for cloud shadows.
 */
export class Noise {
    private p: number[] = new Array(512);

    constructor(seed: number = Math.random()) {
        const permutation = new Array(256).fill(0).map((_, i) => i);

        // Shuffle based on seed
        const random = () => {
            seed = (seed * 9301 + 49297) % 233280;
            return seed / 233280;
        };

        for (let i = 255; i > 0; i--) {
            const j = Math.floor(random() * (i + 1));
            [permutation[i], permutation[j]] = [permutation[j], permutation[i]];
        }

        for (let i = 0; i < 512; i++) {
            this.p[i] = permutation[i & 255];
        }
    }

    private fade(t: number) {
        return t * t * t * (t * (t * 6 - 15) + 10);
    }

    private lerp(t: number, a: number, b: number) {
        return a + t * (b - a);
    }

    private grad(hash: number, x: number, y: number, z: number) {
        const h = hash & 15;
        const u = h < 8 ? x : y;
        const v = h < 4 ? y : h === 12 || h === 14 ? x : z;
        return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v);
    }

    public perlin2(x: number, y: number): number {
        const X = Math.floor(x) & 255;
        const Y = Math.floor(y) & 255;

        x -= Math.floor(x);
        y -= Math.floor(y);

        const u = this.fade(x);
        const v = this.fade(y);

        const A = this.p[X] + Y;
        const AA = this.p[A];
        const AB = this.p[A + 1];
        const B = this.p[X + 1] + Y;
        const BA = this.p[B];
        const BB = this.p[B + 1];

        return this.lerp(v,
            this.lerp(u, this.grad(this.p[AA], x, y, 0), this.grad(this.p[BA], x - 1, y, 0)),
            this.lerp(u, this.grad(this.p[AB], x, y - 1, 0), this.grad(this.p[BB], x - 1, y - 1, 0))
        );
    }
}

import Phaser from 'phaser';
import { MainScene } from '../MainScene';
import { CHUNK_SIZE } from '../../constants';
import { toIso, toCartesian } from '../utils/iso';

export class InfiniteMapSystem {
    private scene: MainScene;
    private generatedChunks: Set<string> = new Set();
    private lastUpdate = 0;

    constructor(scene: MainScene) {
        this.scene = scene;
        this.update();
    }

    public update() {
        const now = this.scene.time.now;
        if (now - this.lastUpdate < 500) return; // Only check chunks twice a second
        this.lastUpdate = now;

        const cam = this.scene.cameras.main;

        // Convert Camera Center (Iso) to Logic (Cartesian) to find the correct chunk
        const center = toCartesian(cam.worldView.centerX, cam.worldView.centerY);

        const chunkX = Math.floor(center.x / CHUNK_SIZE);
        const chunkY = Math.floor(center.y / CHUNK_SIZE);

        // Range for immediate generation
        for (let y = chunkY - 2; y <= chunkY + 2; y++) {
            for (let x = chunkX - 2; x <= chunkX + 2; x++) {
                this.generateChunk(x, y);
            }
        }
    }

    private generateChunk(cx: number, cy: number) {
        const key = `${cx},${cy}`;
        if (this.generatedChunks.has(key)) return;
        this.generatedChunks.add(key);

        const startX = cx * CHUNK_SIZE;
        const startY = cy * CHUNK_SIZE;

        const seed = cx * 1000 + cy;
        const rng = new Phaser.Math.RandomDataGenerator([seed.toString()]);

        const treeCount = rng.between(4, 12);
        for (let i = 0; i < treeCount; i++) {
            const tx = startX + rng.between(20, CHUNK_SIZE - 20);
            const ty = startY + rng.between(20, CHUNK_SIZE - 20);
            // Don't spawn on top of initial spawn area
            if (Phaser.Math.Distance.Between(tx, ty, 400, 400) > 300) {
                this.scene.entityFactory.spawnTree(tx, ty);
            }
        }

        if (rng.frac() < 0.2) {
            const ax = startX + rng.between(50, CHUNK_SIZE - 50);
            const ay = startY + rng.between(50, CHUNK_SIZE - 50);
            if (Phaser.Math.Distance.Between(ax, ay, 400, 400) > 400) {
                // Delegate to AnimalSystem for species-aware spawning
                this.scene.animalSystem.spawnAnimal(ax, ay);
            }
        }

        if (rng.frac() < 0.08) {
            const fx = startX + CHUNK_SIZE / 2;
            const fy = startY + CHUNK_SIZE / 2;
            const radius = rng.between(80, 150);
            this.scene.fertileZones.push(new Phaser.Geom.Circle(fx, fy, radius));

            // Draw fertile zone
            const fGfx = this.scene.add.graphics();
            fGfx.setDepth(-9500);
            const iso = toIso(fx, fy);
            fGfx.fillStyle(0x3e2723, 0.2);
            fGfx.fillEllipse(iso.x, iso.y, radius * 2, radius);
        }
    }
}

import { AnimalSpecies, Season } from "./types";

import { BuildingDef, BuildingType, FactionType, FactionBonus, UnitType, MapSize, MapPreset, UnitStats, FormationType, Age, AgeConfig, DamageType, DamageProfile, ArmorProfile, TechId, TechDef, UnitAbility } from "./types";

export const TILE_SIZE = 32;
// Default Fallback
export const MAP_WIDTH = 2048;
export const MAP_HEIGHT = 2048;

export const STANCE_TETHER_RADIUS = 300; // Max distance to chase from anchor in Defensive stance
// Stress benchmark: render every Nth unit's DOT bob to cap GPU draw count.
// All 5k units remain active and moving; only the visual density is reduced.
