/**
 * Hydraulic and thermal erosion simulation for realistic terrain.
 * Runs after heightmap generation, before biome assignment.
 */
export class ErosionSystem {
  private heightMap: Float32Array;
  private width: number;
  private height: number;
  private random: () => number;

  constructor(
    heightMap: Float32Array,
    width: number,
    height: number,
    seed?: number
  ) {
    this.heightMap = heightMap;
    this.width = width;
    this.height = height;

    // Seeded RNG for deterministic maps
    if (seed !== undefined) {
      let s = seed;
      this.random = () => {
        s = (s * 16807) % 2147483647;
        return (s & 0x7fffffff) / 2147483647;
      };
    } else {
      this.random = Math.random;
    }
  }

  /** Main entry: run both hydraulic and thermal erosion */
  public process(iterations: number = 15): void {
    this.hydraulicErosion(iterations);
    this.thermalErosion(iterations * 2);
  }

  /** Hydraulic erosion: for each cell, move material downhill; smooth locally via flow */
  private hydraulicErosion(iterations: number): void {
    const w = this.width;
    const h = this.height;
    const map = this.heightMap;

    for (let iter = 0; iter < iterations; iter++) {
      const newMap = map.slice(); // copy

      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const idx = y * w + x;
          const height = map[idx];

          // Find lowest downhill neighbor (8-dir)
          let lowestIdx = -1;
          let lowest = height;
          for (let dy = -1; dy <= 1; dy++) {
            for (let dx = -1; dx <= 1; dx++) {
              if (dx === 0 && dy === 0) continue;
              const nx = x + dx, ny = y + dy;
              if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
              const nIdx = ny * w + nx;
              const nh = map[nIdx];
              if (nh < lowest) {
                lowest = nh;
                lowestIdx = nIdx;
              }
            }
          }

          if (lowestIdx === -1) continue; // local minimum (basin)
          const diff = height - lowest;

          // Water moves material at a rate proportional to slope
          const flowRate = Math.min(0.45, diff * 0.001 * 4);
          if (flowRate > 0) {
            // Move material downhill
            newMap[idx] -= flowRate * diff;
            newMap[lowestIdx] += flowRate * diff;
          }
        }
      }

      // Write back
      for (let i = 0; i < map.length; i++) {
        map[i] = newMap[i];
      }
    }
  }

  /** Thermal erosion: talus slope relaxation. Steep slopes collapse until stable angle. */
  private thermalErosion(iterations: number): void {
    const w = this.width;
    const h = this.height;
    const map = this.heightMap;
    const talusAngle = 0.12; // sin of stable slope angle

    for (let iter = 0; iter < iterations; iter++) {
      const newMap = map.slice();

      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const idx = y * w + x;

          // Check 4-neighbor slopes (N,S,E,W)
          const neighbors = [
            { nx: x, ny: y - 1 },
            { nx: x, ny: y + 1 },
            { nx: x - 1, ny: y },
            { nx: x + 1, ny: y },
          ];

          for (const n of neighbors) {
            if (n.nx < 0 || n.nx >= w || n.ny < 0 || n.ny >= h) continue;
            const nIdx = n.ny * w + n.nx;
            const diff = map[idx] - map[nIdx];
            if (diff > talusAngle) {
              // Avalanche: move half the excess
              const move = (diff - talusAngle) * 0.5;
              newMap[idx] -= move;
              newMap[nIdx] += move;
            }
          }
        }
      }

      for (let i = 0; i < map.length; i++) {
        map[i] = newMap[i];
      }
    }
  }
}

