/** Apply hydraulic and thermal erosion to the heightmap for realistic terrain */
private applyErosion(): void {
  const w = this.gridWidth;
  const h = this.gridHeight;
  const iterations = 8; // Balance between quality and generation time

  // Simple in-place erosion (no extra system instance needed)
  // Hydraulic: flow water downhill, deposit sediment
  for (let iter = 0; iter < iterations; iter++) {
    const newMap = this.heightGrid.slice();
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const idx = y * w + x;
        const height = this.heightGrid[idx];

        // Find lowest downhill neighbor
        let lowestIdx = -1;
        let lowest = height;
        for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            if (dx === 0 && dy === 0) continue;
            const nx = x + dx, ny = y + dy;
            if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
            const nIdx = ny * w + nx;
            const nh = this.heightGrid[nIdx];
            if (nh < lowest) {
              lowest = nh;
              lowestIdx = nIdx;
            }
          }
        }

        if (lowestIdx === -1) continue;
        const diff = height - lowest;
        const flowRate = Math.min(0.45, diff * 0.004);
        if (flowRate > 0) {
          newMap[idx] -= flowRate * diff;
          newMap[lowestIdx] += flowRate * diff;
        }
      }
    }
    for (let i = 0; i < this.heightGrid.length; i++) {
      this.heightGrid[i] = newMap[i];
    }
  }

  // Thermal: talus slope relaxation
  const talusAngle = 0.12;
  for (let iter = 0; iter < iterations * 2; iter++) {
    const newMap = this.heightGrid.slice();
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const idx = y * w + x;
        const neighbors = [
          { nx: x, ny: y - 1 }, { nx: x, ny: y + 1 },
          { nx: x - 1, ny: y }, { nx: x + 1, ny: y },
        ];
        for (const n of neighbors) {
          if (n.nx < 0 || n.nx >= w || n.ny < 0 || n.ny >= h) continue;
          const nIdx = n.ny * w + n.nx;
          const diff = this.heightGrid[idx] - this.heightGrid[nIdx];
          if (diff > talusAngle) {
            const move = (diff - talusAngle) * 0.5;
            newMap[idx] -= move;
            newMap[nIdx] += move;
          }
        }
      }
    }
    for (let i = 0; i < this.heightGrid.length; i++) {
      this.heightGrid[i] = newMap[i];
    }
  }
}

