public perlin2(x: number, y: number): number {
  const X = Math.floor(x) & 255;
  const Y = Math.floor(y) & 255;

  x -= Math.floor(x);
  y -= Math.floor(y);

  const u = this.fade(x);
  const v = this.fade(y);

  const A = this.p[X] + Y;
  const AA = this.p[A];
  const AB = this.p[A + 1];
  const B = this.p[X + 1] + Y;
  const BA = this.p[B];
  const BB = this.p[B + 1];

  return this.lerp(v,
    this.lerp(u, this.grad(this.p[AA], x, y, 0), this.grad(this.p[BA], x - 1, y, 0)),
    this.lerp(u, this.grad(this.p[AB], x, y - 1, 0), this.grad(this.p[BB], x - 1, y - 1, 0))
  );
}

/** Ridged multifractal noise — sharp ridges for mountains, bands of parallel peaks */
public ridged2(x: number, y: number, octaves: number = 4, lacunarity: number = 2.0, persistence: number = 0.5): number {
  let value = 0;
  let amplitude = 1;
  let frequency = 1;
  let maxValue = 0;

  for (let i = 0; i < octaves; i++) {
    let noise = Math.abs(this.perlin2(x * frequency, y * frequency));
    // Invert the abs to get ridges (not valleys)
    noise = 1 - noise;
    // Square to sharpen ridges
    noise *= noise;
    value += noise * amplitude;
    maxValue += amplitude;
    amplitude *= persistence;
    frequency *= lacunarity;
  }

  return value / maxValue - 0.5; // Centered at 0
}

